/**
 * Microsoft Teams Node - Version 2
 * Discriminator: resource=onlineMeeting, operation=create
 */


interface Credentials {
  microsoftTeamsOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Create a channel */
export type MicrosoftTeamsV2OnlineMeetingCreateParams = {
  resource: 'onlineMeeting';
  operation: 'create';
  authentication?: 'microsoftTeamsOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The user whose meetings the app creates and manages. From List and user principal names need the User.Read.All application permission; an object ID needs none.
 * @searchListMethod getUsers
 * @displayOptions.show { /authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {"mode":"list","value":""}
 */
    organizerId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The subject of the meeting
 */
    subject: string | Expression<string>;
/**
 * The date and time when the meeting starts
 */
    startDateTime: string | Expression<string>;
/**
 * The date and time when the meeting ends. Must be later than the start time.
 */
    endDateTime: string | Expression<string>;
/**
 * The people to invite to the meeting
 * @default {}
 */
    attendees?: {
        /** Attendee
     */
    attendee?: Array<{
      /** Select the user from the list or by ID. Guest users must be given by their object ID, not by their user principal name.
       * @searchListMethod getUsers
       * @default {"mode":"list","value":""}
       */
      userId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
      /** Presenter takes effect only when Allowed Presenters is set to Specific People
       * @default attendee
       */
      role?: 'attendee' | 'presenter' | Expression<string>;
    }>;
  };
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether attendees can turn on their camera
     * @default true
     */
    allowAttendeeToEnableCamera?: boolean | Expression<boolean>;
    /** Whether attendees can turn on their microphone
     * @default true
     */
    allowAttendeeToEnableMic?: boolean | Expression<boolean>;
    /** The mode of the meeting chat
     * @default enabled
     */
    allowMeetingChat?: 'disabled' | 'enabled' | 'limited' | Expression<string>;
    /** Whether Teams reactions are enabled for the meeting
     * @default true
     */
    allowTeamworkReactions?: boolean | Expression<boolean>;
    /** Who can present in the meeting
     * @default everyone
     */
    allowedPresenters?: 'everyone' | 'organization' | 'organizer' | 'roleIsPresenter' | Expression<string>;
    /** Whether to announce when callers join or leave the meeting
     * @default false
     */
    isEntryExitAnnounced?: boolean | Expression<boolean>;
    /** Who can join the meeting without waiting in the lobby
     * @default organization
     */
    lobbyBypassScope?: 'everyone' | 'invited' | 'organization' | 'organizationAndFederated' | 'organizationExcludingGuests' | 'organizer' | Expression<string>;
    /** Whether to record the meeting automatically
     * @default false
     */
    recordAutomatically?: boolean | Expression<boolean>;
    /** Whether a passcode is required to join the meeting by meeting ID. This setting cannot be changed after the meeting is created.
     * @default false
     */
    passcodeRequired?: boolean | Expression<boolean>;
  };
};

